#!/usr/bin/env bash
# usage: bash art/portraits/gen_moxie.sh <expression> "<expression text>" [suffix]   (run from repo root)
# Derives a Moxie expression from the neutral anchor so only the expression changes.
E="$1"; T="$2"; S="${3:-}"
P="This is the same character sheet portrait redrawn with a different expression. The input image is the approved neutral portrait of Moxie. Redraw it EXACTLY: same character, same drawing style, same line weight, same flat colours and single hard shadow tone, same framing, same scale, same head position and size in the frame, same three-quarter angle facing screen-right, same hair shape (dark-brown messy hair, one high scruffy pigtail visible, loose strands), same yellow over-ear headphones with the dark triangle mark and yellow cable, same pale face-paint stripes and pink blush hatch on the cheek, same black ring choker, same cream crop top with brown star print and dark diagonal buckle strap, same charcoal off-shoulder jacket with yellow lining and pale chevrons. Bare shoulders, warm brown skin, amber eyes. CHANGE ONLY the expression and what is described here: $T Keep the whole head and hair inside the frame with empty headroom above; the bust runs off the bottom edge. Fully transparent background, no backdrop, no text, no border, no watermark, no extra characters. Hands, if shown, have exactly five fingers and wear dark fingerless gloves."
IMG_BG=transparent bash "${IMG_TOOL:-tools/img}" edit "art/portraits/raw/moxie_${E}${S}.png" "$P" art/portraits/raw/moxie_neutral_b.png
